/* Salary-due reminder service worker logic.
 *
 * This file is inlined into the Workbox service worker generated by
 * vite-plugin-pwa (see vite.config.ts → workbox.importScripts) so push
 * works in both dev and production without a separate sw.js file.
 */

self.addEventListener("push", (event) => {
  let data = { title: "PHOJAA95", body: "You have a new notification.", url: "/" };
  try {
    if (event.data) {
      const parsed = event.data.json();
      data = { ...data, ...parsed };
    }
  } catch (err) {
    if (event.data) data.body = event.data.text();
  }

  event.waitUntil(
    self.registration.showNotification(data.title, {
      body: data.body,
      icon: "/pwa-192x192.png",
      badge: "/pwa-192x192.png",
      tag: data.tag || "phojaa95-push",
      renotify: Boolean(data.tag),
      data: { url: data.url || "/" },
      requireInteraction: Boolean(data.requireInteraction),
      vibrate: [200, 100, 200],
    })
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const targetUrl = (event.notification.data && event.notification.data.url) || "/";

  event.waitUntil(
    (async () => {
      const clientList = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      for (const client of clientList) {
        const clientUrl = new URL(client.url);
        if (clientUrl.pathname === targetUrl || clientUrl.pathname === "/") {
          await client.focus();
          if (clientUrl.pathname !== targetUrl) {
            client.navigate?.(targetUrl).catch(() => {});
          }
          return;
        }
      }
      await self.clients.openWindow(targetUrl);
    })()
  );
});
